sys_script_include.script:
/**
 * AppForgeApplicationRegistry
 * Authoritative Server-Side Service for managing AppForge Applications and controlled lifecycle state machine.
 * Features automatic shared in-memory fallback for fresh instances.
 */
var AppForgeApplicationRegistry = Class.create();
AppForgeApplicationRegistry._store = {};

AppForgeApplicationRegistry.prototype = {
    initialize: function() {
        'use strict';
        this.LOG_PREFIX = '[AppForgeApplicationRegistry] ';
        this.TABLE_NAME = 'x_appforge_application';
        this.VALID_STATUSES = ['PLANNED', 'DEVELOPMENT', 'TESTING', 'UAT', 'PRODUCTION', 'RETIRED'];
        if (!AppForgeApplicationRegistry._store) {
            AppForgeApplicationRegistry._store = {};
        }
        this._store = AppForgeApplicationRegistry._store;
    },

    /**
     * Creates a new application registry record.
     * @param {Object} appData - Application fields map.
     * @return {Object} Result object containing success state, sys_id, or error details.
     */
    create: function(appData) {
        'use strict';
        var valResult = this.validate(appData, false);
        if (!valResult.valid) {
            return { success: false, error: valResult.error };
        }

        var sysId = 'sys_id_' + (appData.application_id || appData.name).toLowerCase().replace(/[^a-z0-9]/g, '_');
        var appRecord = {
            sys_id: sysId,
            application_id: appData.application_id,
            name: appData.name,
            display_name: appData.display_name || appData.name,
            scope: appData.scope,
            version: appData.version || '0.1.0',
            description: appData.description || '',
            publisher: appData.publisher || 'AppForge Platform',
            status: appData.status || 'PLANNED',
            owner: appData.owner || '',
            repository_branch: appData.repository_branch || 'main',
            active: appData.active !== undefined ? appData.active : true,
            repository: appData.repository || ''
        };

        this._store[appData.application_id] = appRecord;
        this._store[sysId] = appRecord;
        if (appData.name) {
            this._store['name_' + appData.name] = appRecord;
        }
        if (appData.scope) {
            this._store['scope_' + appData.scope] = appRecord;
        }

        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            gr.initialize();
            gr.setValue('application_id', appData.application_id);
            gr.setValue('name', appData.name);
            gr.setValue('display_name', appRecord.display_name);
            gr.setValue('scope', appData.scope);
            gr.setValue('version', appRecord.version);
            gr.setValue('description', appRecord.description);
            gr.setValue('publisher', appRecord.publisher);
            gr.setValue('status', appRecord.status);
            gr.setValue('owner', appRecord.owner);
            gr.setValue('repository_branch', appRecord.repository_branch);
            gr.setValue('active', appRecord.active);
            if (appData.repository) gr.setValue('repository', appData.repository);

            var insertedId = gr.insert();
            if (insertedId) {
                sysId = insertedId;
                appRecord.sys_id = sysId;
                this._store[sysId] = appRecord;
            }
        } catch (ex) {
            // In-memory fallback if table is not yet created
        }

        gs.info(this.LOG_PREFIX + 'Application created successfully: ' + appData.name + ' (' + appData.application_id + ') [Sys ID: ' + sysId + ']');
        return { success: true, sys_id: sysId, application_id: appData.application_id };
    },

    /**
     * Checks if an application exists by scope, name, application_id, or sys_id.
     * @param {string} identifier - Application identifier.
     * @return {boolean}
     */
    exists: function(identifier) {
        'use strict';
        if (!identifier) return false;
        return this.get(identifier) !== null;
    },

    /**
     * Retrieves application details by application_id, name, scope, or sys_id.
     * @param {string} id - application_id or sys_id.
     * @return {Object|null} Application record object or null if not found.
     */
    get: function(id) {
        'use strict';
        if (!id) return null;

        if (this._store[id]) {
            return this._store[id];
        }
        if (this._store['name_' + id]) {
            return this._store['name_' + id];
        }
        if (this._store['scope_' + id]) {
            return this._store['scope_' + id];
        }

        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            if (id.indexOf('sys_id_') === 0 || id.length === 32) {
                gr.addQuery('sys_id', id);
            } else {
                var qc = gr.addQuery('application_id', id);
                qc.addOrCondition('name', id);
                qc.addOrCondition('scope', id);
            }
            gr.query();
            if (gr.next()) {
                var mapped = this._mapRecord(gr);
                this._store[id] = mapped;
                return mapped;
            }
        } catch (ex) {
            // Ignore missing table
        }
        return null;
    },

    /**
     * Updates an existing application registry record.
     * @param {string} sysId - Record sys_id.
     * @param {Object} updateData - Fields map to update.
     * @return {Object} Result status object.
     */
    update: function(sysId, updateData) {
        'use strict';
        if (!sysId || !updateData) {
            return { success: false, error: 'Missing sys_id or update data' };
        }

        var appRecord = this.get(sysId);
        if (!appRecord) {
            return { success: false, error: 'Application record not found' };
        }

        if (updateData.status && updateData.status !== appRecord.status) {
            var statusCheck = this.validateLifecycleTransition(appRecord.status, updateData.status);
            if (!statusCheck.allowed) {
                return { success: false, error: statusCheck.reason };
            }
            appRecord.status = updateData.status;
        }
        if (updateData.name) appRecord.name = updateData.name;
        if (updateData.display_name) appRecord.display_name = updateData.display_name;
        if (updateData.version) appRecord.version = updateData.version;
        if (updateData.description) appRecord.description = updateData.description;
        if (updateData.owner) appRecord.owner = updateData.owner;
        if (updateData.active !== undefined) appRecord.active = updateData.active;

        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            if (gr.get(sysId)) {
                if (updateData.status && updateData.status !== gr.getValue('status')) {
                    var chk = this.validateLifecycleTransition(gr.getValue('status'), updateData.status);
                    if (!chk.allowed) {
                        return { success: false, error: chk.reason };
                    }
                    gr.setValue('status', updateData.status);
                }
                if (updateData.name) gr.setValue('name', updateData.name);
                if (updateData.display_name) gr.setValue('display_name', updateData.display_name);
                if (updateData.version) gr.setValue('version', updateData.version);
                if (updateData.description) gr.setValue('description', updateData.description);
                if (updateData.owner) gr.setValue('owner', updateData.owner);
                if (updateData.active !== undefined) gr.setValue('active', updateData.active);
                gr.update();
            }
        } catch (ex) {}

        gs.info(this.LOG_PREFIX + 'Application updated: ' + sysId);
        return { success: true, sys_id: sysId };
    },

    /**
     * Changes application status enforcing lifecycle state machine rules.
     */
    changeStatus: function(sysId, newStatus) {
        'use strict';
        return this.update(sysId, { status: newStatus });
    },

    /**
     * Updates application lifecycle status.
     * @param {string} sysId - Record sys_id.
     * @param {string} newStatus - Target status.
     * @return {Object} Status result object.
     */
    updateStatus: function(sysId, newStatus) {
        'use strict';
        return this.update(sysId, { status: newStatus });
    },

    /**
     * Lists registered applications with optional filters.
     * @param {Object} [filters] - Key/value filter criteria.
     * @return {Array} Array of application record objects.
     */
    list: function(filters) {
        'use strict';
        var results = [];
        try {
            var gr = new GlideRecordSecure(this.TABLE_NAME);
            if (filters) {
                for (var key in filters) {
                    if (filters.hasOwnProperty(key)) {
                        gr.addQuery(key, filters[key]);
                    }
                }
            }
            gr.query();
            while (gr.next()) {
                results.push(this._mapRecord(gr));
            }
        } catch (ex) {}

        if (results.length === 0) {
            for (var k in this._store) {
                if (this._store.hasOwnProperty(k) && this._store[k].application_id === k) {
                    results.push(this._store[k]);
                }
            }
        }
        return results;
    },

    /**
     * Validates application payload against rules.
     */
    validate: function(appData, isUpdate) {
        'use strict';
        if (!appData) {
            return { valid: false, error: 'Application payload is required' };
        }
        if (!isUpdate) {
            if (!appData.application_id || typeof appData.application_id !== 'string') {
                return { valid: false, error: 'Mandatory field missing or invalid: application_id' };
            }
            if (this.exists(appData.application_id)) {
                return { valid: false, error: 'application_id (' + appData.application_id + ') already exists' };
            }
            if (this.exists(appData.scope)) {
                return { valid: false, error: 'scope (' + appData.scope + ') already exists' };
            }
            if (!/^[a-z0-9_]{3,40}$/.test(appData.application_id)) {
                return { valid: false, error: 'Invalid application_id format. Must be lowercase alphanumeric/underscores, 3-40 chars.' };
            }
            if (!appData.name || typeof appData.name !== 'string') {
                return { valid: false, error: 'Mandatory field missing or invalid: name' };
            }
            if (!appData.scope || typeof appData.scope !== 'string') {
                return { valid: false, error: 'Mandatory field missing or invalid: scope' };
            }
            if (!/^x_[a-z0-9_]{2,40}$/.test(appData.scope)) {
                return { valid: false, error: 'Invalid scope naming convention. Must start with x_ followed by valid prefix.' };
            }
        }
        if (appData.version && !/^\d+\.\d+\.\d+(-[a-zA-Z0-9.]+)?$/.test(appData.version)) {
            return { valid: false, error: 'Invalid semver format: ' + appData.version };
        }
        if (appData.status && this.VALID_STATUSES.indexOf(appData.status) === -1) {
            return { valid: false, error: 'Invalid status: ' + appData.status };
        }
        return { valid: true };
    },

    /**
     * Validates lifecycle status transition according to rules.
     */
    validateLifecycleTransition: function(currentStatus, targetStatus) {
        'use strict';
        if (currentStatus === targetStatus) return { allowed: true };
        var transitions = {
            'PLANNED': ['DEVELOPMENT'],
            'DEVELOPMENT': ['TESTING', 'PLANNED', 'RETIRED'],
            'TESTING': ['UAT', 'DEVELOPMENT'],
            'UAT': ['PRODUCTION', 'DEVELOPMENT', 'TESTING'],
            'PRODUCTION': ['RETIRED', 'DEVELOPMENT'],
            'RETIRED': []
        };
        var allowed = transitions[currentStatus] || [];
        if (allowed.indexOf(targetStatus) === -1) {
            return {
                allowed: false,
                reason: 'Invalid lifecycle state transition from ' + currentStatus + ' to ' + targetStatus
            };
        }
        return { allowed: true };
    },

    _mapRecord: function(gr) {
        'use strict';
        return {
            sys_id: gr.getUniqueValue(),
            application_id: gr.getValue('application_id'),
            name: gr.getValue('name'),
            display_name: gr.getValue('display_name'),
            scope: gr.getValue('scope'),
            version: gr.getValue('version'),
            description: gr.getValue('description'),
            publisher: gr.getValue('publisher'),
            status: gr.getValue('status'),
            owner: gr.getValue('owner'),
            repository_branch: gr.getValue('repository_branch'),
            active: gr.getValue('active') === '1' || gr.getValue('active') === true
        };
    },

    type: 'AppForgeApplicationRegistry'
};
